package vn.covie.realtime; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; @Component public class SseHeartbeatScheduler {private final SseConnectionRegistry registry;private final vn.covie.ops.ScheduledJobMetrics metrics;public SseHeartbeatScheduler(SseConnectionRegistry registry,vn.covie.ops.ScheduledJobMetrics metrics){this.registry=registry;this.metrics=metrics;}@Scheduled(fixedDelayString="${covie.sse.heartbeat-delay-ms:25000}")public void heartbeat(){metrics.run(vn.covie.ops.ScheduledJobMetrics.Job.SSE_HEARTBEAT,registry::heartbeat);}}
